using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using SalekhPos.Stores.Application.Registers;
using SalekhPos.Stores.Contracts.Registers;
namespace SalekhPos.Stores.Api.Registers;

public static class RegisterEndpoints { public static void MapRegisterEndpoints(this WebApplication app) { var g = app.MapGroup("/api/v1/organizations/{organizationId:guid}/branches/{branchId:guid}/registers").RequireAuthorization().RequireRateLimiting("business"); g.MapPost("", async (Guid organizationId, Guid branchId, CreateRegisterRequest request, HttpContext context, IRegisterCatalog catalog, CancellationToken ct) => { if (!Guid.TryParseExact(context.Request.Headers["Idempotency-Key"], "D", out var op) || op == Guid.Empty) return Invalid(); try { var x = await catalog.CreateAsync(Id(context), new(organizationId, branchId, Guid.NewGuid(), op, request.Code, request.Name), ct); return x.Created ? Results.Created($"/api/v1/organizations/{organizationId:D}/branches/{branchId:D}/registers/{x.Register.Id:D}", x.Register) : Results.Ok(x.Register); } catch (ArgumentException) { return Invalid(); } }); g.MapGet("", async (Guid organizationId, Guid branchId, HttpContext context, IRegisterCatalog catalog, CancellationToken ct) => { if (context.Request.Query.Keys.Any(k => k is not "pageSize" and not "after")) return Invalid(); var size = 50; if (context.Request.Query.TryGetValue("pageSize", out var s) && (!int.TryParse(s, out size) || size is < 1 or > 100)) return Invalid(); Guid? after = null; if (context.Request.Query.TryGetValue("after", out var a)) { if (!Guid.TryParseExact(a, "D", out var id) || id == Guid.Empty) return Invalid(); after = id; } return Results.Ok(await catalog.ListAsync(Id(context), organizationId, branchId, size, after, ct)); }); } private static StoreIdentity Id(HttpContext c) => new(c.User.FindFirst("iss")!.Value, c.User.FindFirst("sub")!.Value); private static IResult Invalid() => Results.Problem(statusCode: 400, title: "The register request is invalid", extensions: new Dictionary<string, object?> { { "code", "invalid_register_request" } }); }
